class Solution {
    vector<pair<char, int>> getRuns(const string& text) {
        vector<pair<char, int>> runs;
        int i = 0, n = text.length();
        while (i < n) {
            int j = i;
            while (j < n && text[j] == text[i]) j++;
            runs.push_back({text[i], j - i});
            i = j;
        }
        return runs;
    }
public:
    int expressiveWords(string s, vector<string>& words) {
        auto s_runs = getRuns(s);
        int ans = 0;
        for (const string& w : words) {
            auto w_runs = getRuns(w);
            if (w_runs.size() != s_runs.size()) continue;
            bool valid = true;
            for (size_t k = 0; k < s_runs.size(); k++) {
                char c1 = s_runs[k].first, c2 = w_runs[k].first;
                int len1 = s_runs[k].second, len2 = w_runs[k].second;
                if (c1 != c2 || len1 < len2 || (len1 > len2 && len1 < 3)) {
                    valid = false;
                    break;
                }
            }
            if (valid) ans++;
        }
        return ans;
    }
};

class Solution {
    private List<int[]> getRuns(String text) {
        List<int[]> runs = new ArrayList<>();
        int i = 0, n = text.length();
        while (i < n) {
            int j = i;
            while (j < n && text.charAt(j) == text.charAt(i)) j++;
            runs.add(new int[]{text.charAt(i), j - i});
            i = j;
        }
        return runs;
    }
    public int expressiveWords(String s, String[] words) {
        List<int[]> sRuns = getRuns(s);
        int ans = 0;
        for (String w : words) {
            List<int[]> wRuns = getRuns(w);
            if (wRuns.size() != sRuns.size()) continue;
            boolean valid = true;
            for (int k = 0; k < sRuns.size(); k++) {
                int c1 = sRuns.get(k)[0], c2 = wRuns.get(k)[0];
                int len1 = sRuns.get(k)[1], len2 = wRuns.get(k)[1];
                if (c1 != c2 || len1 < len2 || (len1 > len2 && len1 < 3)) {
                    valid = false;
                    break;
                }
            }
            if (valid) ans++;
        }
        return ans;
    }
}

var expressiveWords = function(s, words) {
    function getRuns(text) {
        const runs = [];
        let i = 0;
        while (i < text.length) {
            let j = i;
            while (j < text.length && text[j] === text[i]) j++;
            runs.push([text[i], j - i]);
            i = j;
        }
        return runs;
    }
    const sRuns = getRuns(s);
    let ans = 0;
    for (const w of words) {
        const wRuns = getRuns(w);
        if (wRuns.length !== sRuns.length) continue;
        let valid = true;
        for (let k = 0; k < sRuns.length; k++) {
            const [c1, len1] = sRuns[k];
            const [c2, len2] = wRuns[k];
            if (c1 !== c2 || len1 < len2 || (len1 > len2 && len1 < 3)) {
                valid = false;
                break;
            }
        }
        if (valid) ans++;
    }
    return ans;
};
